:root{--bg:#f7f7f5;--panel:rgba(248,248,246,.84);--text:#202124;--muted:#777b82;--line:rgba(255,255,255,.32);--blue:#4f78f6;--blue2:#edf2ff;--shadow:0 10px 34px rgba(30,35,50,.12);--bubble-bg:rgba(237,240,245,.88);--bubble-size:15px}
