function localRecipe(query){
 const q=normText(query),recipes=[
  {match:/mercimek corbasi|corba/,name:'Kırmızı mercimek çorbası',ingredients:['1 su bardağı kırmızı mercimek','1 küçük soğan ve 1 küçük havuç','1 yemek kaşığı sıvı yağ, 5 su bardağı su veya et suyu','Tuz, karabiber; isteğe göre kimyon'],steps:['Soğanı ve havucu yağda 2–3 dakika kavur.','Yıkanmış mercimeği ve suyu ekle; mercimek yumuşayana kadar yaklaşık 20 dakika kaynat.','Blenderdan geçir, tuz ve baharatı ekleyip 2 dakika daha pişir.']},
  {match:/menemen/,name:'Menemen',ingredients:['3 yumurta','2 domates ve 2 sivri biber','1 yemek kaşığı zeytinyağı veya tereyağı','Tuz, karabiber; isteğe göre pul biber'],steps:['Biberleri doğrayıp yağda 3–4 dakika yumuşat.','Küp doğranmış domatesleri ekleyip suyunu biraz çekene kadar pişir.','Yumurtaları kır, tuz ve baharatı ekle; istediğin kıvama gelince ocaktan al.']},
  {match:/tavuk/,name:'Pratik tavuk sote',ingredients:['400 g kuşbaşı tavuk','1 soğan ve 1 biber','1 domates veya 1 yemek kaşığı domates salçası','1 yemek kaşığı yağ, tuz, karabiber ve kekik'],steps:['Tavayı ısıtıp yağı ve tavuğu ekle; suyunu salıp çekene kadar 6–8 dakika pişir.','Doğranmış soğan ve biberi ekleyip 4 dakika kavur.','Domatesi, tuzu ve baharatı ekle; kapağı kapalı şekilde 8–10 dakika pişir.']},
  {match:/makarna|spagetti/,name:'Domates soslu makarna',ingredients:['250 g makarna','2 olgun domates veya 1 su bardağı domates püresi','1 diş sarımsak','1 yemek kaşığı zeytinyağı, tuz; isteğe göre kaşar veya fesleğen'],steps:['Makarnayı tuzlu kaynar suda paket süresine göre haşla; yarım bardak haşlama suyunu ayır.','Yağda ince doğranmış sarımsağı 30 saniye çevir, domatesi ekleyip 8 dakika pişir.','Makarnayı sosa ve biraz haşlama suyuna ekleyip karıştır; peynirle servis et.']},
  {match:/pilav/,name:'Tane tane pirinç pilavı',ingredients:['1 su bardağı pirinç','1,5 su bardağı sıcak su veya et suyu','1 yemek kaşığı tereyağı ve 1 yemek kaşığı sıvı yağ','Tuz'],steps:['Pirinci yıkayıp 10 dakika ılık tuzlu suda beklet, sonra süz.','Yağları tencerede erit; pirinci 2–3 dakika kavur.','Sıcak suyu ve tuzu ekle. Kısık ateşte kapağı kapalı 12 dakika pişir; 10 dakika demlendir.']},
  {match:/kek|tatli|tatli|tatli/,name:'Kolay yoğurtlu kek',ingredients:['2 yumurta','1 su bardağı şeker ve 1 su bardağı yoğurt','Yarım su bardağı sıvı yağ','2 su bardağı un, 1 paket kabartma tozu ve vanilin'],steps:['Yumurta ve şekeri köpürene kadar çırp; yoğurt ve yağı ekle.','Unu ve kabartma tozunu eleyerek karışıma kat, fazla çırpmadan karıştır.','Yağlanmış kalıpta önceden ısıtılmış 180°C fırında yaklaşık 30–35 dakika pişir.']}
 ];
 const recipe=recipes.find(item=>item.match.test(q))||recipes.find(item=>item.name==='Domates soslu makarna');
 return '<h2>'+recipe.name+' (2–3 kişilik)</h2><p><b>Malzemeler</b></p><ul>'+recipe.ingredients.map(item=>'<li>'+item+'</li>').join('')+'</ul><p><b>Pratik hazırlık</b></p><ol>'+recipe.steps.map(step=>'<li>'+step+'</li>').join('')+'</ol>';
}
