248:   if(window.FoVerseNewsIntent?.isNewsDetailRequest(q))return window.FoVerseNewsIntent.detailSearchQuery(q)||q;
249:   const newsQuery=window.FoVerseNewsIntent?.searchQuery(q);
250:   if(newsQuery)return newsQuery;
251:   const normalized=q.toLocaleLowerCase('tr-TR').replace(/[?!.]+$/,'').trim();
252:   if(/^(gündemde ne var|gundemde ne var|gündem|gundem|günse|gunse|bugün neler oldu|bugun neler oldu|son gelişmeler|son gelismeler|haberler|güncel haberler|guncel haberler)$/.test(normalized))return 'Türkiye ve dünya gündem son dakika haberleri';
253:   let out=q
