256:     .replace(/[?!.]+$/,'')
257:     .replace(/\s+/g,' ').trim();
258:   const tokens=out.split(/\s+/).filter(Boolean);
259:   if(tokens.length>12)out=tokens.slice(0,12).join(' ');
260:   return out.slice(0,500);
261: }
