function classifyIntent(query) {
  const n = normalize(query);
  if (/\b(dolar|usd|eur|euro|sterlin|gbp|jpy|yen|kur|kurlar|exchange|currency|doviz|döviz)\b/.test(n)) return 'CURRENCY';
  if (/\b(saat kac|saat su an kac|current time|what time|tarih nedir|bugun gunlerden ne|bugunun tarihi|today.?s date)\b/.test(n)) return 'TIME';
  if (/\b(sosyal medya|twitter|x hesab|instagram|tiktok|trend topic|gundem basligi|viral)\b/.test(n)) return 'SOCIAL';
  if (/\b(siyaset|ekonomi|oyun|gundem|haber|son dakika|spor|teknoloji|saglik|dunya|turkiye)\b/.test(n)) return 'NEWS_CATEGORY';
  return 'GENERAL';
}

function isNewsIntent(query) {
  return classifyIntent(query) === 'NEWS_CATEGORY';
}

