  async function searchWeb(query){const queryKey=buildSearchQuery(query),intent=window.FoVerseNewsIntent?.classifyIntent(query),isLiveNews=intent==='NEWS_CATEGORY'||intent==='SOCIAL';if(isLiveNews&&liveData.lastNewsQuery===queryKey&&Date.now()-liveData.lastNewsAt<60000&&liveData.lastNewsItems.length)return {ok:true,items:liveData.lastNewsItems};try{const r=await fetch('/api/search',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({query:queryKey,count:8}),signal:abort?.signal});const data=await r.json().catch(()=>({}));if(!r.ok||!Array.isArray(data.items)||!data.items.length)return {ok:false,reason:r.status===503&&data.code==='SEARCH_NOT_CONFIGURED'?'Canlı web araması şu anda yapılandırılmamış (Google arama API anahtarı veya arama motoru kimliği eksik). Bu nedenle güncel kaynakları doğrulayamadım. Genel bilgi verebilirim; ancak bunu canlı olarak doğrulanmış gibi sunmayacağım.':data.error||'Canlı web araması şu anda kullanılamıyor; güncel kaynakları doğrulayamadım.'};const items=data.items.slice(0,8).map(x=>({title:String(x.title||'Kaynak').slice(0,300),url:String(x.url||''),snippet:String(x.snippet||'').slice(0,1200)})).filter(x=>/^https?:\/\//i.test(x.url));if(!items.length)return {ok:false,reason:'Arama sonuçları geçerli kaynak bağlantısı içermiyordu.'};if(isLiveNews){liveData.lastNewsQuery=queryKey;liveData.lastNewsItems=items;liveData.lastNewsAt=Date.now();rememberNewsList(items)}return {ok:true,items}}catch(e){if(abort&&abort.signal.aborted)throw e;return {ok:false,reason:'Web araması bu oturumda erişilebilir değil.'}}}
