test('priority intents, categories, and Istanbul clock are recognized', () => {
  assert.equal(intent.classifyIntent('Bugün dolar kaç TL?'), 'CURRENCY');
  assert.equal(intent.classifyIntent('Euro kaç lira?'), 'CURRENCY');
