<script src="/news-intent.js"></script>
<script>
(()=>{'use strict';
const syncViewportHeight=()=>document.documentElement.style.setProperty('--app-height',Math.round(window.visualViewport?.height||window.innerHeight)+'px');
syncViewportHeight();window.addEventListener('resize',syncViewportHeight);window.visualViewport?.addEventListener('resize',syncViewportHeight);
const $=id=>document.getElementById(id); const memory={};
const store={get(k,f=null){try{const v=localStorage.getItem(k);return v===null?f:v}catch(e){return memory[k]??f}},set(k,v){try{localStorage.setItem(k,v);return true}catch(e){memory[k]=v;return false}}};
let mode='Smart',attachedText='',attachedName='',busy=false,abort=null,chatHistory=[],lastSearchContext=null;
function applyAppearance(){
  const font=store.get('foverseFont','modern'),bubble=store.get('foverseBubble','rounded'),theme=store.get('foverseTheme','slate'),size=store.get('foverseSize','15');
  document.body.dataset.font=font;document.body.dataset.bubble=bubble;document.body.dataset.theme=theme;
  document.documentElement.style.setProperty('--bubble-size',size+'px');
  const fontSelect=$('fontSelect'),bubbleSelect=$('bubbleSelect'),themeSelect=$('themeSelect'),sizeSelect=$('sizeSelect');
  if(fontSelect)fontSelect.value=font;if(bubbleSelect)bubbleSelect.value=bubble;if(themeSelect)themeSelect.value=theme;if(sizeSelect)sizeSelect.value=size;
}
applyAppearance();
function applyWallpaper(){
  const enabled=store.get('foverseWallpaper','on')==='on';const video=$('liveWallpaper'),button=$('wallpaperToggle');
  video.style.display=enabled?'block':'none';button.classList.toggle('off',!enabled);button.setAttribute('aria-pressed',String(enabled));button.textContent=enabled?'◉':'○';
  if(enabled)video.play().catch(()=>{});else video.pause();
}
applyWallpaper();
try{mode=store.get('geminiMode','Smart');document.querySelectorAll('.mode-row button').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('modeBadge').textContent=mode}catch(e){}
try{$('apiKey').value=store.get('geminiKey','');$('toneSelect').value=store.get('geminiTone','Clear and helpful');$('modelSelect').value=store.get('geminiModel','auto')}catch(e){}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function cleanAnswerText(s){
  let text=String(s||'');
  text=text.replace(/==+\s*([^=\n]+?)\s*==+/g,'$1');
  const blocked=/HTTP\/[\d.]+|\b(?:RESOURCE_EXHAUSTED|PERMISSION_DENIED|INVALID_ARGUMENT|NOT_FOUND)\b|status(?: code)?\s*[:=]?\s*\d{3}|api[_ -]?key|exception\s*:|stack trace|traceback|request failed|another api key|provide (?:a|another) api key|enter (?:a|another) api key|invalid api key|quota exceeded|too many requests/i;
  text=text.split('\n').filter(line=>{
    const t=line.trim();
    if(blocked.test(t)) return false;
    if(/^at\s+/.test(t)||/^\^+/.test(t)) return false;
    if(/^(error|code|message)\s*[:=]/i.test(t)) return false;
    return true;
  }).join('\n');
  return text.trim().replace(/\n{3,}/g,'\n\n');
}
function md(s){let x=esc(cleanAnswerText(s));x=x.replace(/```([^\n]*)\n([\s\S]*?)```/g,(m,l,c)=>'<pre><code>'+c+'</code></pre>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/^### (.+)$/gm,'<h3>$1</h3>').replace(/^## (.+)$/gm,'<h2>$1</h2>').replace(/^[-*] (.+)$/gm,'<li>$1</li>').replace(/((?:<li>.*<\/li>\n?)+)/g,'<ul>$1</ul>').replace(/^(\d+)\. (.+)$/gm,'<li>$2</li>').replace(/\n\n/g,'</p><p>').replace(/\n/g,'<br>');return '<p>'+(x||'Bu yanıtı güvenli biçimde oluşturamadım. Sorunu yeniden ifade edebilir misin?')+'</p>'}
function addBriefGreeting(q,answer){const n=normText(q),rest=n.replace(/^(?:selam(?:un aleykum)?|merhaba|hello|hi)\b[\s,!.]*/,'').trim();if(rest.length<4)return answer;const plain=String(answer||'').replace(/<[^>]*>/g,' ').trim();if(/^(?:merhaba|selam|hello|hi)\b/i.test(plain))return answer;return '<p>Merhaba! Hemen yanıtlayayım.</p>'+answer}
function clock(){try{const d=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Istanbul',weekday:'short',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date());$('clock').textContent=d+' · Europe/Istanbul (UTC+3)'}catch(e){$('clock').textContent='Local time'}}clock();setInterval(()=>{try{clock()}catch(e){}},30000);
function autoGrow(){try{const el=$('input');el.style.height='42px';el.style.height=Math.min(el.scrollHeight,130)+'px'}catch(e){}}
$('input').addEventListener('input',()=>{try{autoGrow()}catch(e){}});
$('input').addEventListener('keydown',e=>{try{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send()}}catch(e){}});
function addMsg(role,html){try{const inner=$('chatInner');const h=$('hero');if(h)h.remove();const el=document.createElement('div');el.className='message '+role;if(role==='user')el.innerHTML='<div class="bubble">'+esc(html)+'</div>';else el.innerHTML='<div class="ai-mark"></div><div class="answer">'+html+'<div class="answer-actions"><button class="copyBtn" title="Copy">⧉</button><button class="regenBtn" title="Regenerate">↻</button><button class="ttsBtn" title="Read aloud">◖</button></div></div>';inner.appendChild(el);$('chat').scrollTop=$('chat').scrollHeight}catch(e){}}
const topicGroups={gaming:['oyun','game','gaming','steam','playstation','xbox','nintendo','konsol','oyun sektoru','oyun studio','esports','espor','fps','rpg','patch','yama','dlc','gameplay','fragman','trailer'],technology:['teknoloji','yapay zeka','ai','telefon','bilgisayar','yazilim','donanim','chip','gpu','cpu','android','iphone','robot','siber'],sports:['spor','futbol','basketbol','tenis','mac','lig','takim','gol','transfer','nba','football'],cinema:['film','sinema','dizi','anime','manga','aktor','aktris','yonetmen','box office'],finance:['finans','borsa','hisse','kripto','bitcoin','ekonomi','faiz','enflasyon','yatirim','dolar','piyasa'],science:['bilim','arastirma','uzay','fizik','kimya','biyoloji','astronomi','deney','kesif'],education:['egitim','universite','okul','ders','ogretmen','ogrenci','mufredat','sinav','yks','tyt','ayt','lgs'],culture:['kultur','sanat','kitap','muzik','sergi','miras','edebiyat','festival'],everyday:['yemek','tarif','saglik','uyku','temizlik','seyahat','gezi','alisveris','ev','gunluk','everyday','recipe','travel']};
const normText=s=>String(s||'').toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i');
const stopWords=new Set('selam merhaba lutfen bana bir ne var nedir nasil ne zaman kim nerede neden hakkinda ile icin ve veya bu su da de mi the a an is are what how tell me about latest current news gundeminde gundemi gundem oyun game'.split(/\s+/));
function topicOf(q){const n=normText(q);for(const [topic,words] of Object.entries(topicGroups))if(words.some(w=>n.includes(normText(w))))return topic;return ''}
function meaningfulTerms(q){return (normText(q).match(/[\p{L}\p{N}]{3,}/gu)||[]).filter(t=>!stopWords.has(t))}
function relevantText(q,text){const terms=meaningfulTerms(q),n=normText(text),topic=topicOf(q),specific=topic?(topicGroups[topic].filter(w=>!['oyun','game','gaming','spor','teknoloji','bilim','egitim','kultur','film','sinema','finans','ekonomi'].includes(w)&&n.includes(normText(w))).length):0;const shared=terms.filter(t=>!['oyun','game','gaming','gundem','news','latest','current'].includes(t)&&n.includes(t)).length;if(topic&&/gundem|haber|news|latest|current|today|bugun/.test(normText(q)))return shared>=1||specific>=2;return shared>=1||specific>=1}
function ragContext(q){try{if(!attachedText)return '';const nq=normText(q),summary=/\b(summarize|summary|ozet|ders not|study guide|tumunu|tamamini|whole document|entire file)\b/i.test(nq),useFile=/(ekli|dosya|notlar|notlarim|belge|attached|file|document|these notes|based on this|bunlari|bunlardan|oyun tasarla|game design|game maker)/i.test(nq);const chunks=attachedText.split(/\n\s*\n/).flatMap(p=>p.length>900?p.match(/[\s\S]{1,850}(?:\s|$)/g)||[p]:[p]);if(summary||useFile)return chunks.slice(0,10).join('\n\n').slice(0,7000);return chunks.map((c,i)=>{const terms=meaningfulTerms(q),n=normText(c),topic=topicOf(q);let score=terms.reduce((v,t)=>v+(n.includes(t)?1:0),0);if(topic&&topicGroups[topic].some(w=>n.includes(normText(w))))score+=1;return {c,i,score}}).filter(x=>x.score>=1&&relevantText(q,x.c)).sort((a,b)=>b.score-a.score||a.i-b.i).slice(0,5).map(x=>x.c).join('\n\n').slice(0,7000)}catch(e){return ''}}
function runtimeClock(){
 const now=new Date(),localZone=Intl.DateTimeFormat().resolvedOptions().timeZone||'Europe/Istanbul';
 const istanbul=new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul',weekday:'long',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(now);
 const iso=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);
 const weekday=new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul',weekday:'long'}).format(now);
 return {now,istanbul,iso,weekday,localZone};
}
function localAnswer(q){
 const raw=String(q||'').trim(),t=raw.toLocaleLowerCase('tr-TR'),ctx=ragContext(raw),clock=runtimeClock();
 const time=()=>clock.istanbul+' (Europe/Istanbul, UTC+3; cihaz zaman dilimi: '+clock.localZone+')';
 if(/(sen kimsin|neler yapabilirsin|what are you|who are you|what can you do)/i.test(t))return '<h2>Ben FoVerse AI</h2><p>Türkçe ve İngilizce yanıt veren; açıklama, çeviri, özet, kod, planlama ve oyun tasarımı çalışmalarında yardımcı olan bir tarayıcı asistanıyım. API anahtarı varsa desteklenen modelden yanıt alırım; dosya eklediğinizde ilgili bölümleri bağlam olarak kullanırım.</p>';
 if(/(saat kaç|kaç saat|şu an saat|şimdiki saat|tarih nedir|bugünün tarihi|bugün günlerden ne|bugün hangi gün|günlerden ne|current time|date today|what date is it|what day is it|what time is it)/i.test(t))return '<h2>İstanbul’da şimdi</h2><p><b>'+esc(time())+'</b></p><p>Bugün: <b>'+esc(clock.weekday)+', '+esc(clock.iso)+'</b></p>';
 if(/(yarın (günlerden ne|hangi gün)|tomorrow)/i.test(t)){const d=new Date(clock.now);d.setDate(d.getDate()+1);return '<h2>Yarın</h2><p>'+esc(new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul',weekday:'long',year:'numeric',month:'2-digit',day:'2-digit'}).format(d))+' (Europe/Istanbul)</p>'}
 if(/(dün (günlerden ne|hangi gün)|yesterday)/i.test(t)){const d=new Date(clock.now);d.setDate(d.getDate()-1);return '<h2>Dün</h2><p>'+esc(new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul',weekday:'long',year:'numeric',month:'2-digit',day:'2-digit'}).format(d))+' (Europe/Istanbul)</p>'}
 if(/(çevir|tercüme|translate)/i.test(t)){let m=raw.match(/[“"']([^”"']+)[”"']\s*(?:→|to|into|- )\s*([\p{L} ]+)/iu)||raw.match(/(?:çevir|translate)\s+(.+?)\s+(?:to|into|→)\s+([\p{L} ]+)/iu);if(m)return '<h2>Çeviri</h2><p><b>'+esc(m[1].trim())+'</b> → <b>'+esc(m[2].trim())+'</b></p><p>İfadenin geçtiği cümleyi veya kullanım bağlamını paylaşırsan daha doğal bir karşılık seçebilirim.</p>';return '<h2>Çeviri için metin ve hedef dil gerekli</h2><p>Örnek: “Good morning” → Türkçe.</p>'}
 if(/(merhaba|selam|hello|^hi\b)/i.test(t)&&!topicOf(t))return '<h2>Merhaba!</h2><p>Sorunu veya üzerinde çalıştığınız konuyu yazın; doğrudan yanıtlamaya çalışayım.</p>';
if(topicOf(t)==='gaming'&&/(gundem|haber|news|latest|current|bugun|son durum)/.test(normText(t)))return '<h2>Oyun gündemi: takip etmeye değer başlıklar</h2><p><small>Aşağıdakiler canlı haber iddiası değil; oyun sektöründeki genel eğilimlerdir.</small></p><ul><li><b>Canlı servis oyunları:</b> Sezon güncellemelerinde içerik miktarından çok oynanış dengesi, eşleştirme ve oyuncu geri bildiriminin ne kadar hızlı karşılandığı belirleyici. Büyük yamaların ardından sunucu durumu ve platformlar arası ilerleme de yakından izlenir.</li><li><b>Çıkış takvimi ve ertelemeler:</b> Büyük yapımların kesin çıkış tarihi, oynanış gösterimi ve ön sipariş/ön yükleme ayrıntıları gerçek gündem maddeleridir; tanıtım videosu tek başına çıkışın yakın olduğuna kanıt sayılmaz.</li><li><b>Platform ve iş modeli:</b> Konsol/PC duyuruları, abonelik kütüphaneleri, mağaza indirimleri ve çapraz oyun desteği oyuncuların neye erişebildiğini etkiler. Duyurunun hangi bölge ve platformları kapsadığını kontrol etmek gerekir.</li><li><b>Bağımsız oyunlar:</b> Festivaller ve demo etkinlikleri yeni oyun keşfi için verimli; tür, demo süresi ve kayıt aktarımı satın alma kararına yardımcı olur.</li></ul><p>İstersen bunu <b>PC, PlayStation, Xbox, Nintendo, mobil</b> ya da belirli bir oyun için daha odaklı bir gündem özetine çevirebilirim.</p>';
if(/(gundem|haber|news|latest|current|bugun|son durum)/.test(normText(t))&&topicOf(t)&&topicOf(t)!=='gaming'){const insights={technology:'Teknoloji gündemini değerlendirirken ürün duyurusunu gerçek erişilebilirlikten ayır: çıkış tarihi, bölge, fiyat ve destek süresi önemlidir. Yapay zekâ tarafında model yeteneği kadar maliyet, veri gizliliği ve iş akışına entegrasyon; donanımda ise performans başına güç tüketimi ve yazılım desteği belirleyicidir.',sports:'Spor gündeminde sonucu; sakatlık, kadro rotasyonu, fikstür yoğunluğu ve maç içi taktikle birlikte okumak gerekir. Transfer haberlerinde resmî imza, kulüp görüşmesi ve iddia aşamasını ayır; tek maçlık performansı sezon eğilimi sanma.',cinema:'Sinema ve anime gündeminde yeni duyuruları yayın takvimi, dağıtım bölgesi ve platforma göre ayır. Fragman ilgi ölçer ama nihai kaliteyi göstermez; devam yapımlarında yaratıcı ekip, uyarlama kapsamı ve bölüm/film formatı daha anlamlı sinyallerdir.',finance:'Finans gündeminde piyasa hareketini tek bir başlığa bağlamak yerine faiz beklentisi, enflasyon, şirket sonuçları ve risk iştahını birlikte izle. Kısa vadeli fiyat hareketi kesin yön veya kişisel yatırım tavsiyesi değildir; para birimi ve zaman aralığı sonucu değiştirir.',science:'Bilim gündeminde basın duyurusunu hakemli çalışma, ön baskı ve tekrarlanmış bulgudan ayır. Örneklem büyüklüğü, yöntem, belirsizlik aralığı ve bağımsız doğrulama; iddianın ne kadar güçlü olduğunu gösterir.',education:'Eğitim gündeminde politika duyurusunun hangi yaş, sınav dönemi ve kurumları kapsadığını kontrol et. Öğrenme araçlarını değerlendirirken erişilebilirlik, öğretmen iş yükü, ölçülebilir öğrenme kazanımı ve veri gizliliği birlikte ele alınmalı.',culture:'Kültür gündeminde etkinlik duyurusunun tarih, mekân, erişim ve bilet koşullarını; sanat/kültür tartışmalarında ise eserin bağlamı, üreticilerin katkısı ve temsil biçimini ayrı değerlendir. Geçici trend ile kalıcı kültürel etki aynı şey değildir.'};return '<h2>'+esc(topicOf(t)[0].toLocaleUpperCase('tr-TR')+topicOf(t).slice(1))+' gündemi: yararlı çerçeve</h2><p><small>Bu, doğrulanmış güncel haber listesi değil; konuyu sağlıklı değerlendirmek için genel bir çerçevedir.</small></p><p>'+esc(insights[topicOf(t)]||insights.culture)+'</p><p>Belirli bir ülke, tarih aralığı, takım, ürün veya yapım söylersen odağı daraltabilirim.</p>';}
