115: async function rssSearch(query, count) {
116:   const params = new URLSearchParams({ q: query, hl: 'tr', gl: 'TR', ceid: 'TR:tr' });
117:   const response = await fetch('https://news.google.com/rss/search?' + params.toString(), {
118:     method: 'GET',
119:     headers: { Accept: 'application/rss+xml, application/xml;q=0.9, text/xml;q=0.8', 'User-Agent': 'FoVerse-AI-Search/1.0' },
120:   });
121:   if (!response.ok) throw new Error(`Google News RSS failed: ${response.status}`);
122:   const xml = await response.text();
123:   const items = [];
124:   const itemMatches = xml.match(/<item\b[^>]*>[\s\S]*?<\/item>/gi) || [];
125:   for (const block of itemMatches) {
126:     const get = (tag) => block.match(new RegExp(`<${tag}\\b[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i'))?.[1] || '';
127:     const title = cleanText(get('title'));
128:     const url = validHttpUrl(cleanText(get('link')));
129:     if (!title || !url) continue;
130:     const sourceTag = cleanText(get('source'));
131:     const dashMatch = title.match(/\s+-\s+([^]+)$/);
132:     const pipeMatch = title.match(/\s*\|\s*([^|]+)$/);
133:     const suffixMatch = dashMatch || pipeMatch;
134:     const source = cleanText(sourceTag || (suffixMatch ? suffixMatch[1] : ''));
135:     const headline = cleanText(suffixMatch ? title.slice(0, suffixMatch.index).trim() : title);
136:     const description = cleanText(get('description'));
137:     const titleKey = headline.toLocaleLowerCase('tr-TR').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
138:     const descriptionKey = description.toLocaleLowerCase('tr-TR').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
139:     const snippet = !description || descriptionKey === titleKey || descriptionKey.includes(titleKey) || titleKey.includes(descriptionKey) ? '' : description;
140:     items.push({
141:       title: headline.slice(0, 300),
142:       url,
143:       snippet: snippet.slice(0, 1200),
144:       source,
145:       date: cleanText(get('pubDate')).slice(0, 100),
146:     });
147:     if (items.length >= count) break;
148:   }
149:   return items;
150: }
