312:     const dashMatch = title.match(/\s+-\s+([^]+)$/);
313:     const pipeMatch = title.match(/\s*\|\s*([^|]+)$/);
314:     const suffixMatch = dashMatch || pipeMatch;
315:     const source = cleanText(sourceTag || (suffixMatch ? suffixMatch[1] : ''));
316:     const headline = cleanText(suffixMatch ? title.slice(0, suffixMatch.index).trim() : title);
317:     const description = cleanText(get('description'));
318:     const titleKey = headline.toLocaleLowerCase('tr-TR').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
319:     const descriptionKey = description.toLocaleLowerCase('tr-TR').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
320:     const snippet = !description || descriptionKey === titleKey || descriptionKey.includes(titleKey) || titleKey.includes(descriptionKey) ? '' : description;
321:     items.push({
322:       title: headline.slice(0, 300), url,
323:       snippet: snippet.slice(0, 1200),
324:       source,
325:       date: cleanText(get('pubDate')).slice(0, 100),
326:     });
327:     if (items.length >= count) break;
328:   }
329:   return dedupeAndSort(items).slice(0, count);
