332: async function gdeltSearch(query, count, signal) {
333:   const params = new URLSearchParams({
334:     query,
335:     mode: 'ArtList',
336:     format: 'json',
337:     maxrecords: String(count),
338:     sort: 'HybridRel',
339:   });
340:   const response = await fetch(`https://api.gdeltproject.org/api/v2/doc/doc?${params}`, {
341:     method: 'GET',
342:     headers: { Accept: 'application/json', 'User-Agent': 'FoVerse-AI-Search/1.0' },
343:     signal,
344:   });
345:   if (!response.ok) throw new Error(`GDELT search failed: ${response.status}`);
346:   const data = await response.json();
347:   return (Array.isArray(data.articles) ? data.articles : []).slice(0, count).map((article) => {
348:     const url = validHttpUrl(article.url);
349:     let source = cleanText(article.domain);
350:     try { if (!source && url) source = cleanText(new URL(url).hostname); } catch {}
351:     return {
352:       title: cleanText(article.title || 'Kaynak').slice(0, 300),
353:       url,
354:       snippet: cleanText(article.snippet || '').slice(0, 1200),
355:       source: source.slice(0, 200),
356:       date: cleanText(article.seendate || article.datetime || '').slice(0, 100),
357:     };
358:   }).filter((item) => item.title && item.url);
359: }

