341:     method: 'GET',
342:     headers: { Accept: 'application/json', 'User-Agent': 'FoVerse-AI-Search/1.0' },
343:     signal,
344:   });
345:   if (!response.ok) throw new Error(`GDELT search failed: ${response.status}`);
346:   const data = await response.json();
347:   return (Array.isArray(data.articles) ? data.articles : []).slice(0, count).map((article) => {
348:     const url = validHttpUrl(article.url);
349:     let source = cleanText(article.domain);
350:     try { if (!source && url) source = cleanText(new URL(url).hostname); } catch {}
