352:       title: cleanText(article.title || 'Kaynak').slice(0, 300),
353:       url,
354:       snippet: cleanText(article.snippet || '').slice(0, 1200),
355:       source: source.slice(0, 200),
356:       date: cleanText(article.seendate || article.datetime || '').slice(0, 100),
357:     };
358:   }).filter((item) => item.title && item.url);
359: }

