  if(intent==='CURRENCY'||intent==='TIME'||intent==='SOCIAL')return false;
  if(intent==='NEWS_CATEGORY')return true;
  if(window.FoVerseNewsIntent?.isNewsIntent(query))return true;
  const currentShort=/^(gündemde ne var|gundemde ne var|gündem|gundem|günse|gunse|bugün neler oldu|bugun neler oldu|haberler|güncel haberler|guncel haberler|son gelişmeler|son gelismeler|son dakika)$/i.test(q.replace(/[?!.]+$/,'').trim());
  if(currentShort)return true;
